('hospitality', 'Hotels & Hospitality', 'Guest experience built on security', 'Surveillance, access control, fire safety and seamless Wi-Fi.', '["Guest Wi-Fi that''s fast and isolated from operations","Access control for rooms, floors and back-of-house","Surveillance of public and service areas","Fire safety across guest floors and kitchens"]'::jsonb, '["wifi-installation","access-control-systems","cctv-installation","fire-alarm-systems","intercom-systems","network-security"]'::jsonb, '["Seamless, secure guest connectivity","Controlled access across the property","Safer guests and staff","Compliant fire and life safety"]'::jsonb, 'modern hotel lobby with discreet security and access systems', 'Hotel', 5),
('retail', 'Retail Stores', 'Loss prevention and connected retail', 'CCTV, alarms, access control and networking.', '["Shrinkage and theft at point of sale and stockrooms","Alarm and intrusion detection out of hours","Multi-site surveillance and viewing","Reliable POS and inventory network"]'::jsonb, '["cctv-installation","burglar-alarm-systems","access-control-systems","lan-wan","video-monitoring","perimeter-intrusion"]'::jsonb, '["Reduced shrinkage and clearer evidence","Early intrusion detection and alerts","Multi-site oversight from one platform","Reliable retail network"]'::jsonb, 'retail store interior with discreet security cameras', 'ShoppingBag', 6),
