('government', 'Government & Public Sector', 'Secure and compliant public infrastructure', 'Security and IT infrastructure engineered for government and public institutions.', '["Strict compliance and audit requirements","Protection of sensitive public data","Controlled access to government facilities","Resilient, reliable public infrastructure"]'::jsonb, '["network-security","access-control-systems","cctv-installation","security-assessment","server-data-centre","fire-alarm-systems"]'::jsonb, '["Compliant, auditable security posture","Protected sensitive data","Controlled, monitored access","Resilient public-sector infrastructure"]'::jsonb, 'government building with security and access control systems', 'Landmark', 10),
('religious', 'Religious Organizations', 'Safe, welcoming places of worship', 'Surveillance, access control, fire safety and AV networking.', '["Surveillance of large gathering spaces","Access control for offices and valuable areas","Fire safety for crowded gatherings","AV and network for services and streaming"]'::jsonb, '["cctv-installation","access-control-systems","fire-alarm-systems","wifi-installation","intercom-systems","burglar-alarm-systems"]'::jsonb, '["Safer gatherings and premises","Controlled access to sensitive areas","Compliant fire safety","Connected services and outreach"]'::jsonb, 'large place of worship interior with discreet security systems', 'Church', 11),
