('smb', 'Small & Medium Businesses', 'Enterprise-grade security, right-sized', 'Right-sized networking, security and IT support.', '["Limited in-house IT and security expertise","Need for protection without big budgets","Reliable IT support without a full team","Scalable systems that grow with the business"]'::jsonb, '["managed-services","computer-it-support","network-installation","cctv-installation","firewall-endpoint-protection","wifi-installation"]'::jsonb, '["Professional IT and security without an in-house team","Predictable, manageable costs","Reliable day-to-day operations","Systems that scale with growth"]'::jsonb, 'small business office with networking and security systems', 'Store', 13)
