INSERT INTO "Solution" ("id", "name", "summary", "description", "components", "outcomes", "bestFor", "iconName", "sortOrder") VALUES
('unified-security', 'Unified Security & Surveillance', 'CCTV, access control, alarms and monitoring integrated into one security platform.', 'We integrate surveillance, access control, alarms and monitoring into one platform so your security works as a single, responsive system.', '["cctv-installation","access-control-systems","burglar-alarm-systems","video-monitoring","perimeter-intrusion"]'::jsonb, '["Incidents detected, recorded and alerted in one flow","Single platform instead of disconnected systems","Faster, better-coordinated response","Clearer evidence and audit trails"]'::jsonb, '["corporate","warehouse","industrial","retail","residential"]'::jsonb, 'ShieldCheck', 1),
('resilient-network', 'Resilient Network Infrastructure', 'Cabling, switching, routing and Wi-Fi engineered for performance, security and growth.', 'We engineer a resilient network foundation with structured cabling, managed switching, segmentation and wireless.', '["structured-cabling","lan-wan","wifi-installation","network-installation","network-maintenance"]'::jsonb, '["Reliable connectivity for every system and user","Clean segmentation of voice, data, surveillance and guests","Future-proofed headroom for growth","Documented, supportable infrastructure"]'::jsonb, '["corporate","education","healthcare","industrial","hospitality"]'::jsonb, 'Network', 2),
('cyber-defence', 'Cyber Defence Programme', 'Layered cybersecurity — assessment, firewalls, endpoint protection and monitoring.', 'We build a layered cyber-defence programme — assessment, next-gen firewalls, endpoint protection, intrusion detection and ongoing monitoring.', '["security-assessment","network-security","firewall-endpoint-protection","intrusion-detection","managed-services"]'::jsonb, '["Defensible, documented security posture","Blocked malware, ransomware and intrusion attempts","Visibility and alerting on threats","Stronger compliance position"]'::jsonb, '["finance","corporate","government","healthcare","smb"]'::jsonb, 'ShieldCheck', 3),
('life-safety', 'Life Safety & Fire Protection', 'Fire detection, alarm and safety systems engineered for compliance and rapid evacuation.', 'We engineer comprehensive fire detection, alarm and safety solutions — detectors, call points, sounders, emergency lighting and integration.', '["fire-alarm-systems","fire-detection-safety","door-access-systems","managed-services"]'::jsonb, '["Early, reliable fire detection","Compliant, insurable life-safety systems","Safe, coordinated evacuation","Documented for inspection"]'::jsonb, '["hospitality","healthcare","education","industrial","warehouse"]'::jsonb, 'Flame', 4),
('smart-building', 'Smart Building Integration', 'Security, automation, lighting and energy unified into one manageable platform.', 'We integrate security, access, surveillance, lighting, climate and energy into one smart-building platform.', '["smart-building-solutions","access-control-systems","intercom-systems","cctv-installation","wifi-installation"]'::jsonb, '["Simpler, smarter building operations","Lower energy costs through automation","Better security and comfort","One interface instead of many"]'::jsonb, '["corporate","hospitality","residential","government","healthcare"]'::jsonb, 'Building2', 5),
('managed-it', 'Managed IT & Security', 'Your IT and security under continuous care — monitoring, maintenance and support.', 'We manage your IT and security under one agreement — proactive monitoring, preventive maintenance, priority support and ongoing improvement.', '["managed-services","computer-it-support","network-maintenance","network-security","systems-installation-maintenance"]'::jsonb, '["Predictable costs, fewer surprises","Healthier systems that fail less","Prioritised, faster response","A strategic partner, not just a vendor"]'::jsonb, '["corporate","smb","finance","healthcare","education"]'::jsonb, 'ServerCog', 6)
