-- ─── Testimonials ─────────────────────────────────────────
INSERT INTO "Testimonial" ("id", "quote", "authorRole", "sector", "rating", "projectType") VALUES
('t1', 'Allison Global treated our office network and security as one system, not separate purchases. The handover documentation alone was better than anything we''d had from previous vendors.', 'Operations Manager', 'corporate', 5, 'Network & Cybersecurity Build'),
('t2', 'After we rolled out their CCTV and alarm package across our branches, after-hours losses dropped noticeably. Being able to view every store from one app changed how we manage security.', 'Retail Operations Lead', 'retail', 5, 'Multi-Site Surveillance & Alarms'),
('t3', 'The fire alarm and access control integration gave us real confidence for evacuation compliance. They didn''t just install — they explained, trained our team, and stayed for support.', 'Facilities Manager', 'hospitality', 5, 'Fire Safety & Access Integration'),
('t4', 'Our perimeter had been a problem for years. Their beam detection and triggered cameras finally gave us early warning instead of discovering break-ins the next morning.', 'Warehouse Supervisor', 'warehouse', 5, 'Perimeter & Inventory Protection'),
('t5', 'Our server room was a mess before Allison Global rebuilt it. Proper racks, UPS, cooling and backup — and they''ve managed it since. Downtime basically stopped being a worry.', 'IT Lead', 'healthcare', 5, 'Server Room & Managed IT'),
('t6', 'What stood out was the honesty. They told us where we were overspending and where we genuinely needed more. That kind of counsel is rare with vendors.', 'Business Owner', 'smb', 5, 'Security Assessment & IT Support'),
('t7', 'As a growing school, we needed campus Wi-Fi and surveillance done properly. They heat-mapped everything and the coverage is the best we''ve ever had.', 'School Administrator', 'education', 5, 'Campus Wi-Fi & Surveillance'),
('t8', 'Gate access control with video intercoms transformed how our estate handles visitors. Residents feel safer and management finally has proper records of who comes and goes.', 'Estate Facility Manager', 'residential', 5, 'Estate Access & Smart Security')
ON CONFLICT ("id") DO UPDATE SET "quote" = EXCLUDED."quote", "authorRole" = EXCLUDED."authorRole", "sector" = EXCLUDED."sector", "rating" = EXCLUDED."rating", "projectType" = EXCLUDED."projectType", "updatedAt" = CURRENT_TIMESTAMP;

-- ─── Projects ──────────────────────────────────────────────
INSERT INTO "Project" ("id", "title", "category", "industry", "services", "location", "scope", "description", "highlights", "imageQuery", "year", "featured") VALUES
('p-001', 'Multi-Site Retail Surveillance & Alarm Rollout', 'Surveillance & Alarms', 'retail', '["cctv-installation","burglar-alarm-systems","video-monitoring","lan-wan"]'::jsonb, 'Lagos & Ogun', '8 retail locations · unified monitoring', 'A regional retail chain needed consistent surveillance and intrusion detection across eight branches. We standardised CCTV and alarm systems across all sites and unified them on a single monitoring platform.', '["Standardised CCTV and alarms across 8 branches","Centralised multi-site monitoring platform","Out-of-hours intrusion alerts to management","Reduced shrinkage and faster incident review"]'::jsonb, 'retail store surveillance camera system installation', '2025', true),
('p-002', 'Corporate Office Network & Cybersecurity Build', 'Network & Cybersecurity', 'corporate', '["structured-cabling","lan-wan","network-security","firewall-endpoint-protection","access-control-systems"]'::jsonb, 'Lagos (Victoria Island)', '6-floor HQ · 300+ users', 'A growing professional-services firm needed a secure, segmented network for a new headquarters. We engineered the cabling, switching, firewalling and access control for a six-floor office.', '["Structured cabling and managed switching across 6 floors","Segmented networks for staff, guests and building systems","Next-gen firewall and endpoint protection deployed","Access control with audit trail across the building"]'::jsonb, 'modern corporate office server room and network racks', '2025', true),
('p-003', 'Hotel Fire Safety & Guest Access Integration', 'Fire Safety & Access', 'hospitality', '["fire-alarm-systems","access-control-systems","intercom-systems","cctv-installation"]'::jsonb, 'Lekki, Lagos', 'Boutique hotel · 60 rooms', 'A boutique hotel required compliant fire detection and guest access control that didn''t compromise the guest experience.', '["Addressable fire alarm system with full coverage","Door access integrated with fire-alarm evacuation release","Discreet surveillance of public and service areas","Video intercom with remote gate unlock"]'::jsonb, 'boutique hotel lobby fire safety and access control systems', '2025', true),
('p-004', 'Warehouse Perimeter & Inventory Protection', 'Perimeter & Surveillance', 'warehouse', '["perimeter-intrusion","cctv-installation","access-control-systems","burglar-alarm-systems"]'::jsonb, 'Agbara, Ogun', 'Large logistics warehouse', 'A logistics operator was losing inventory to perimeter breaches. We deployed active infrared beam detection along the perimeter, integrated with CCTV.', '["Perimeter beam detection along the full boundary","CCTV triggered recording on perimeter breach","Access control for staff and vehicles","Integrated alarm and alerting"]'::jsonb, 'warehouse perimeter security infrared beam cameras at night', '2025', false),
('p-005', 'School Campus Wi-Fi & Surveillance', 'Networking & Surveillance', 'education', '["wifi-installation","cctv-installation","lan-wan","access-control-systems"]'::jsonb, 'Ibadan, Oyo', 'Campus · multiple buildings', 'A school needed campus-wide Wi-Fi for staff and students, plus surveillance to improve safety.', '["Heat-mapped enterprise Wi-Fi across the campus","Segmented networks for staff, students and guests","CCTV coverage of key campus areas","Access control for labs and offices"]'::jsonb, 'school campus wifi access points and security cameras', '2025', false),
('p-006', 'Hospital Server Room & Resilient IT', 'IT Infrastructure', 'healthcare', '["server-data-centre","network-security","computer-it-support","fire-detection-safety"]'::jsonb, 'Surulere, Lagos', 'Hospital data centre', 'A hospital needed resilient IT infrastructure for patient systems and data.', '["Server room fit-out with racks, UPS and cooling","Backup and recovery strategy with tested restore","Network hardening and segmentation","Ongoing managed IT support"]'::jsonb, 'hospital server room with racks ups and cooling', '2025', false),
('p-007', 'Construction Site Mobile Surveillance', 'Surveillance', 'construction', '["cctv-installation","video-monitoring","perimeter-intrusion","burglar-alarm-systems"]'::jsonb, 'Eko Atlantic, Lagos', 'Live construction site', 'A developer was losing materials to night-time theft on a live construction site. We deployed mobile surveillance with perimeter detection and remote monitoring.', '["Mobile surveillance adaptable to site changes","Perimeter detection with remote alerts","No fixed infrastructure required","Reduced material losses"]'::jsonb, 'construction site mobile surveillance cameras at night', '2025', false),
('p-008', 'Estate Access Control & Smart Security', 'Access & Surveillance', 'residential', '["access-control-systems","cctv-installation","intercom-systems","burglar-alarm-systems","wifi-installation"]'::jsonb, 'Lekki Phase 1, Lagos', 'Gated residential estate', 'A gated estate wanted controlled access for residents, staff and visitors, plus surveillance at entry points and common areas.', '["Gate access control with video intercoms","Resident and visitor credential management","CCTV coverage of entry and common areas","Estate-wide Wi-Fi for management"]'::jsonb, 'gated residential estate gate access control and cameras', '2025', false),
('p-009', 'Manufacturing Plant Fire Safety & Network', 'Fire Safety & Network', 'industrial', '["fire-detection-safety","fire-alarm-systems","structured-cabling","cctv-installation"]'::jsonb, 'Ikeja, Lagos', 'Manufacturing facility', 'A manufacturing plant needed compliant fire safety and a reliable network across a large industrial facility.', '["Comprehensive fire detection and safety systems","Structured cabling across the production floor","Surveillance of operational and asset areas","Compliance-ready documentation"]'::jsonb, 'manufacturing plant fire safety and network infrastructure', '2025', false)
ON CONFLICT ("id") DO UPDATE SET "title" = EXCLUDED."title", "category" = EXCLUDED."category", "industry" = EXCLUDED."industry", "services" = EXCLUDED."services", "location" = EXCLUDED."location", "scope" = EXCLUDED."scope", "description" = EXCLUDED."description", "highlights" = EXCLUDED."highlights", "imageQuery" = EXCLUDED."imageQuery", "year" = EXCLUDED."year", "featured" = EXCLUDED."featured", "updatedAt" = CURRENT_TIMESTAMP;

-- ─── FAQs ─────────────────────────────────────────────────
INSERT INTO "Faq" ("id", "category", "question", "answer", "sortOrder") VALUES
('f1', 'Services & Scope', 'What services does Allison Global offer?', 'We cover six core domains: Network & Connectivity, Cybersecurity, Surveillance & Monitoring, Access Control & Automation, Alarm & Fire Safety, and IT Infrastructure & Support. Each spans multiple specialist services — from structured cabling to managed IT — so your network, security and IT systems are handled by one engineering-led team.', 1),
('f2', 'Services & Scope', 'Do you work on both homes and businesses?', 'Yes. We serve homes and residential estates, offices, businesses, institutions and industries. The scale differs, but the engineering approach is the same — assess, design, install, integrate and support.', 2),
('f3', 'Services & Scope', 'Can you integrate CCTV, access control, alarms and networking?', 'Absolutely — integration is a core strength. Many security issues come from systems that don''t talk to each other. We design CCTV, access control, alarms and networking to work as one platform.', 3),
('f4', 'Services & Scope', 'Do you supply the equipment, or only install?', 'We do both. We assess, design, supply, install, integrate and maintain. Equipment is sourced through proper channels as genuine, warrantied product.', 4),
('f5', 'Process & Engagement', 'How does a project typically start?', 'It starts with a consultation and site assessment. A senior engineer visits your site, understands your needs and risks, and documents what''s actually required. You then receive a clear proposal with scope, equipment and pricing before any work begins.', 1),
('f6', 'Process & Engagement', 'Do you provide documentation after installation?', 'Yes — every project is handed over with as-built documentation, system diagrams, credentials, manuals and a maintenance schedule.', 2),
('f7', 'Process & Engagement', 'Can you work with equipment we already have?', 'In many cases, yes. During the assessment we review your existing infrastructure and advise what can be retained, upgraded or replaced.', 3),
('f8', 'Process & Engagement', 'How long does a typical installation take?', 'It depends on scope. A small CCTV or access control install can take a day or two; a full office network or multi-site rollout takes longer and is phased to minimise disruption. You''ll get a clear timeline in your proposal.', 4),
('f9', 'Support & Maintenance', 'Do you offer ongoing support and maintenance?', 'Yes — through our Managed Services & Technical Support plans. We provide preventive maintenance, monitoring, priority support and ongoing improvement under a predictable agreement.', 1),
('f10', 'Support & Maintenance', 'How quickly can you respond to support requests?', 'Managed-support clients have defined response-time SLAs, with a target priority response of under 4 hours for critical issues. For ad-hoc support, we respond as quickly as our engineering schedule allows.', 2),
('f11', 'Support & Maintenance', 'Is there a warranty on your installations?', 'Installations are covered by a workmanship warranty so defects in our installation work are put right. Equipment itself carries the manufacturer''s warranty, which we help you manage.', 3),
('f12', 'Security & Data', 'How do you keep our network and data secure?', 'Security is built in, not bolted on. We design segmented networks, deploy next-gen firewalls and endpoint protection, follow least-privilege access, and document credentials securely.', 1),
('f13', 'Security & Data', 'Can you help us with cybersecurity if we have no in-house team?', 'Yes — that''s exactly what our Cybersecurity services and Managed Services are designed for. We act as your security partner.', 2),
('f14', 'Security & Data', 'Do you offer security assessments and audits?', 'Yes. Our Security Assessment & Consultation service evaluates your network, systems and physical security against real threats and produces a prioritised, jargon-free remediation roadmap.', 3),
('f15', 'Location & Coverage', 'Where are you based, and which areas do you cover?', 'We''re headquartered in Lagos, Nigeria, and deliver projects nationwide with rapid-response support across major Nigerian cities.', 1),
('f16', 'Location & Coverage', 'Can you support multiple sites across different locations?', 'Yes. We frequently deploy unified surveillance, networking and security across multiple branches or sites, with centralised management and monitoring.', 2)
ON CONFLICT ("id") DO UPDATE SET "category" = EXCLUDED."category", "question" = EXCLUDED."question", "answer" = EXCLUDED."answer", "sortOrder" = EXCLUDED."sortOrder", "updatedAt" = CURRENT_TIMESTAMP;

-- ─── Blog Posts ───────────────────────────────────────────
INSERT INTO "BlogPost" ("slug", "title", "excerpt", "category", "readTime", "date", "author", "authorRole", "imageQuery", "content", "tags", "featured") VALUES
('how-to-choose-cctv-system-nigeria', 'How to Choose the Right CCTV System for Your Business in Nigeria', 'Resolution, coverage, storage and night capability matter far more than camera count.', 'Surveillance', '7 min read', '2025-10-12', 'Agu Chisom Alvin', 'Founder & CEO, Allison Global', 'cctv security camera installation on building exterior', '[{"body":"Most businesses buy CCTV the same way: a few cameras, a recorder, and hope. Here''s how to specify a CCTV system that delivers usable footage when it matters."},{"heading":"Start with what you need to see","body":"Before discussing camera models, define your risk areas: entrances, exits, point-of-sale counters, stockrooms, loading bays, car parks and cash-handling points."},{"heading":"Resolution and lensing matter more than camera count","body":"A single 4K camera with the right lens can outperform four cheap ones."},{"heading":"Don''t forget night capability","body":"Most incidents happen after dark. Cameras need either strong infrared or true low-light sensors."},{"heading":"Size storage to your retention needs","body":"Footage is only useful if it''s still there when you discover an incident."},{"heading":"Make it viewable and integrated","body":"Modern CCTV should be viewable from anywhere and integrated with your other security."},{"body":"A well-designed CCTV system is an investment that pays for itself the first time it deters a loss or provides the evidence you need."}]'::jsonb, '["CCTV","Surveillance","Security"]'::jsonb, true),
('cybersecurity-basics-nigerian-smes', 'Cybersecurity Basics Every Nigerian SME Should Get Right First', 'Before you invest in advanced tools, get these fundamentals right.', 'Cybersecurity', '8 min read', '2025-10-28', 'Allison Global Team', 'Allison Global Insights', 'cybersecurity firewall network protection concept', '[{"body":"Small and medium businesses are now a primary target for cybercriminals. The good news: the majority of attacks can be prevented with fundamentals."},{"heading":"1. A real firewall, not a consumer router","body":"Your internet router is not a security device. A next-generation firewall with threat prevention is the single highest-impact upgrade."},{"heading":"2. Endpoint protection that detects behaviour","body":"Free antivirus matches against known signatures. Modern EDR watches behaviour."},{"heading":"3. Segment your network","body":"A flat network means one infected device can reach everything."},{"heading":"4. Backups that survive an attack","body":"Ransomware encrypts backups too if they''re connected. Follow the 3-2-1 rule."},{"heading":"5. Multi-factor authentication everywhere","body":"Stolen passwords still drive most breaches."},{"heading":"6. Patching and updates","body":"Known vulnerabilities in unpatched software are an open door."},{"body":"Get these six right and you''ve closed the door on the majority of attacks."}]'::jsonb, '["Cybersecurity","Network Security","SME"]'::jsonb, true),
('structured-cabling-future-proofing', 'Why Structured Cabling Is the Investment You''ll Thank Yourself For', 'The cabling behind your network, CCTV and access systems outlasts almost everything else.', 'Networking', '6 min read', '2025-10-10', 'Agu Chisom Alvin', 'Founder & CEO, Allison Global', 'structured cabling network rack tidy patch panel', '[{"body":"Structured cabling is invisible — until something breaks."},{"heading":"Everything runs on the cable","body":"Your network, phones, CCTV, access control, Wi-Fi and IT systems all depend on the same cabling foundation."},{"heading":"Standards, testing and documentation","body":"Proper structured cabling follows TIA/EIA standards."},{"heading":"Future-proofing is cheap insurance","body":"Installing higher-specification cable costs marginally more during installation."},{"heading":"Tidy racks save money","body":"A well-dressed, labelled rack makes troubleshooting fast."},{"body":"Cabling is the foundation everything else stands on."}]'::jsonb, '["Networking","Cabling","Infrastructure"]'::jsonb, false),
('access-control-vs-traditional-keys', 'Access Control vs Traditional Keys: The Business Case', 'Keys get lost, copied and never returned. Access control gives you control and audit trails.', 'Access Control', '6 min read', '2025-09-22', 'Allison Global Team', 'Allison Global Insights', 'access control card reader door entry system', '[{"body":"Keys have served buildings for centuries, but for modern businesses they''re a liability."},{"heading":"Control who goes where, and when","body":"Access control lets you define exactly which doors each person can open."},{"heading":"Audit trails change investigations","body":"When something goes wrong, access control tells you who was where."},{"heading":"Instant revocation, no rekeying","body":"When staff leave, or a fob is lost, you revoke access in seconds."},{"heading":"It integrates with your other systems","body":"Modern access control integrates with CCTV, alarms, and time attendance."},{"body":"Access control isn''t just about replacing keys — it''s about gaining control, visibility and integration."}]'::jsonb, '["Access Control","Security"]'::jsonb, false),
('fire-safety-compliance-nigeria', 'Fire Safety Compliance: What Nigerian Businesses Should Know', 'Fire safety isn''t just good practice — it''s a regulatory and insurance matter.', 'Fire Safety', '7 min read', '2025-09-05', 'Allison Global Team', 'Allison Global Insights', 'fire alarm smoke detector and sounder on ceiling', '[{"body":"Fire safety is a life-safety matter — but it''s also a regulatory and insurance one."},{"heading":"Detection designed for the space","body":"Different spaces need different detection."},{"heading":"Audible and visual alerting","body":"Everyone on the premises must be alerted."},{"heading":"Addressable systems for larger sites","body":"For larger premises, addressable fire alarm systems identify exactly which detector triggered."},{"heading":"Integration for safe evacuation","body":"Fire alarms should integrate with access control to release doors."},{"heading":"Documentation and maintenance","body":"Compliance requires documented design, installation records and a maintenance schedule."},{"body":"Fire safety is one area where cutting corners costs lives and money."}]'::jsonb, '["Fire Safety","Compliance"]'::jsonb, false),
('managed-services-vs-break-fix', 'Managed IT Services vs Break-Fix: The Real Cost Comparison', 'Break-fix feels cheaper — until you count the downtime.', 'IT Support', '6 min read', '2025-08-19', 'Allison Global Team', 'Allison Global Insights', 'IT support engineer monitoring systems dashboard', '[{"body":"Many businesses still operate on a break-fix model. It feels cheaper because there''s no monthly fee."},{"heading":"Break-fix means downtime you pay for","body":"Every hour a system is down is lost productivity."},{"heading":"Managed services catch issues early","body":"With monitoring and preventive maintenance, managed services catch failures before they become outages."},{"heading":"Predictable costs, predictable support","body":"Managed services give you a predictable monthly cost and defined response SLAs."},{"heading":"Security stays current","body":"Under break-fix, security patching happens only when someone notices."},{"body":"For most businesses, managed services cost less than the downtime, surprises and risk of break-fix."}]'::jsonb, '["Managed Services","IT Support"]'::jsonb, false)
ON CONFLICT ("slug") DO UPDATE SET "title" = EXCLUDED."title", "excerpt" = EXCLUDED."excerpt", "category" = EXCLUDED."category", "readTime" = EXCLUDED."readTime", "date" = EXCLUDED."date", "author" = EXCLUDED."author", "authorRole" = EXCLUDED."authorRole", "imageQuery" = EXCLUDED."imageQuery", "content" = EXCLUDED."content", "tags" = EXCLUDED."tags", "featured" = EXCLUDED."featured", "updatedAt" = CURRENT_TIMESTAMP;

-- ─── Services (all 26) ────────────────────────────────────
-- I''ll insert the services using the category slugs from the Category table
DO $$
DECLARE
  cat_network TEXT; cat_cyber TEXT; cat_surv TEXT; cat_access TEXT; cat_alarm TEXT; cat_infra TEXT;
BEGIN
  SELECT id INTO cat_network FROM "Category" WHERE slug = 'network-connectivity';
  SELECT id INTO cat_cyber FROM "Category" WHERE slug = 'cybersecurity';
  SELECT id INTO cat_surv FROM "Category" WHERE slug = 'surveillance-monitoring';
  SELECT id INTO cat_access FROM "Category" WHERE slug = 'access-control';
  SELECT id INTO cat_alarm FROM "Category" WHERE slug = 'alarm-fire-safety';
  SELECT id INTO cat_infra FROM "Category" WHERE slug = 'it-infrastructure';

  -- Network & Connectivity
  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('structured-cabling', 'Structured Cabling', cat_network, 'A cabling foundation engineered to carry your business for decades', 'Standards-compliant copper, fibre and rack cabling with proper labelling, testing and certification.', 'We design and install Cat6/Cat6A copper and fibre-optic cabling to TIA/EIA standards.', '["Slow, intermittent connections caused by poorly terminated or tangled cabling.","No documentation, so every change becomes a guessing game.","Cabling that fails under high bandwidth or distance demands.","Messy racks that make troubleshooting and expansion painful."]'::jsonb, 'We engineer a structured cabling system around your building, bandwidth and growth plans.', '[{"title":"Site survey & cable design","description":"Cable routes, outlet counts, rack locations and material take-off tailored to your building."},{"title":"Copper & fibre installation","description":"Cat6/Cat6A and OS2/OM4 fibre pulled, terminated and dressed to standard."},{"title":"Patch panels & racks","description":"Wall and floor racks, patch panels, cable managers and tidy, labelled patching."},{"title":"Certification testing","description":"Fluke-class testers validate every link."},{"title":"As-built documentation","description":"Outlet schedules, rack diagrams and cable labels."}]'::jsonb, '["Reliable gigabit and multi-gig performance to every outlet","Clean, documented infrastructure that scales with you","Fewer outages and faster fault-finding","Future-proofed headroom for CCTV, Wi-Fi and IT growth"]'::jsonb, '["Cat6/Cat6A","Single-mode & multimode fibre","LSZH cabling","Cable certification testers","Racks & cable management"]'::jsonb, '["lan-wan","network-installation","wifi-installation","cctv-installation","access-control-systems"]'::jsonb, '["corporate","education","healthcare","industrial","warehouse"]'::jsonb, true, 'Cable', 1)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "tagline" = EXCLUDED."tagline", "shortDescription" = EXCLUDED."shortDescription", "overview" = EXCLUDED."overview", "problem" = EXCLUDED."problem", "solution" = EXCLUDED."solution", "deliverables" = EXCLUDED."deliverables", "benefits" = EXCLUDED."benefits", "tech" = EXCLUDED."tech", "relatedServices" = EXCLUDED."relatedServices", "relatedIndustries" = EXCLUDED."relatedIndustries", "featured" = EXCLUDED."featured", "iconName" = EXCLUDED."iconName", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('lan-wan', 'LAN / WAN Solutions', cat_network, 'Switching, routing and segmentation done right', 'Layer 2/3 switching, VLANs, routing and inter-site connectivity designed for performance and segmentation.', 'A flat network is a slow, insecure network. We design and deploy LAN and WAN infrastructure with managed switching.', '["Congested, flat networks where CCTV traffic competes with business data.","Intermittent dropouts from consumer-grade switches and routers.","No segmentation between guest, staff and device networks.","Multi-site connectivity that''s slow, insecure or both."]'::jsonb, 'We architect your LAN/WAN with enterprise switching, VLAN design, routing and secure inter-site links.', '[{"title":"Network architecture","description":"Topology, VLAN plan, IP scheme and segmentation strategy."},{"title":"Managed switching","description":"Layer 2/3 switches configured with VLANs, QoS and link aggregation."},{"title":"Routing & WAN","description":"Router configuration, inter-site VPN and WAN aggregation where needed."},{"title":"Segmentation","description":"Separate networks for data, voice, surveillance, guests and IoT."},{"title":"Documentation & handover","description":"Configuration backup, IP plan and operational runbook."}]'::jsonb, '["Clean separation of traffic for security and performance","Reliable connectivity that scales with users and devices","Better application performance with proper QoS","Secure multi-site connectivity"]'::jsonb, '["Managed L2/L3 switches","VLANs & 802.1Q","Site-to-site VPN","QoS","Link aggregation"]'::jsonb, '["network-installation","structured-cabling","network-security","firewall-endpoint-protection","wifi-installation"]'::jsonb, '["corporate","education","healthcare","finance","industrial"]'::jsonb, false, 'Router', 2)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('wifi-installation', 'Wi-Fi Installation & Optimization', cat_network, 'Coverage you can actually rely on, in every corner', 'Heat-mapped wireless deployments and optimisation for offices, hotels, campuses and large homes.', 'Dead zones and dropped Wi-Fi cost productivity and frustrate users. We design wireless networks using proper site surveys.', '["Dead spots and weak signal in key areas.","Wi-Fi that slows to a crawl when many users connect.","Guest Wi-Fi sharing the same network as staff.","Roaming that drops calls and sessions between access points."]'::jsonb, 'We survey your environment, design access-point placement for true coverage, and configure enterprise Wi-Fi with seamless roaming.', '[{"title":"Wireless site survey","description":"Heat-mapped coverage planning based on your walls, floors and layout."},{"title":"Access point deployment","description":"Enterprise APs placed and mounted for optimal coverage and capacity."},{"title":"SSID & security design","description":"Separate networks for staff, guests and devices with WPA2/3 security."},{"title":"Roaming & optimisation","description":"Seamless 802.11r/k/v roaming, band steering and channel tuning."},{"title":"Performance validation","description":"Post-installation testing confirming coverage and throughput."}]'::jsonb, '["Reliable coverage everywhere it matters","Higher capacity for many simultaneous users","Secure guest access isolated from business data","Seamless roaming without dropped connections"]'::jsonb, '["Wi-Fi 6 / 6E access points","Controller & cloud-managed Wi-Fi","Mesh & roaming protocols","WPA3","Heat-map survey tools"]'::jsonb, '["network-installation","lan-wan","network-security","structured-cabling","smart-building-solutions"]'::jsonb, '["hospitality","education","corporate","residential","retail"]'::jsonb, true, 'Wifi', 3)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('network-installation', 'Network Installation & Infrastructure', cat_network, 'End-to-end network build, from rack to endpoint', 'Turnkey network installation — design, supply, configuration, commissioning and handover.', 'A great network design means nothing without clean execution. We handle the full installation.', '["Equipment bought but never properly configured.","Installations with no testing, no documentation and no support.","Vendors who disappear after deployment.","Networks that work on day one and degrade from day two."]'::jsonb, 'We install your network end-to-end — supply, configure, test, commission and document.', '[{"title":"Equipment supply","description":"Genuine enterprise equipment sourced and supplied with warranty."},{"title":"Rack build & cabling","description":"Clean rack assembly with proper cable management."},{"title":"Configuration","description":"Switches, routers, APs and security configured to design."},{"title":"Commissioning & testing","description":"End-to-end validation before we hand over."},{"title":"Handover & documentation","description":"As-built docs, credentials and operational runbook."}]'::jsonb, '["One accountable partner for the whole build","Stable, tested network from day one","Documented and supportable long-term","Genuine, warrantied equipment"]'::jsonb, '["Enterprise switches & routers","Racks & UPS","Network configuration management","Documentation tooling"]'::jsonb, '["structured-cabling","lan-wan","wifi-installation","network-security","network-maintenance"]'::jsonb, '["corporate","education","healthcare","industrial","warehouse"]'::jsonb, false, 'Network', 4)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('network-maintenance', 'Network Maintenance & Support', cat_network, 'Keep the backbone healthy, not just installed', 'Preventive maintenance, monitoring and rapid-response support for your network infrastructure.', 'Networks degrade silently. Our maintenance and support keeps your network healthy with scheduled health checks.', '["Slow deterioration nobody notices until something fails.","Outdated firmware with known vulnerabilities.","No monitoring, so outages are discovered by users first.","Slow vendor response when the network goes down."]'::jsonb, 'We keep your network under maintenance — proactive monitoring, scheduled servicing, firmware updates and priority response.', '[{"title":"Health checks","description":"Scheduled audits of switching, routing and wireless performance."},{"title":"Monitoring","description":"Proactive monitoring that flags issues before users do."},{"title":"Firmware management","description":"Planned updates and security patching."},{"title":"Priority response","description":"Defined SLA response times for support clients."},{"title":"Change management","description":"Configuration backups and controlled change."}]'::jsonb, '["Fewer surprise outages","Security patches applied on schedule","Faster resolution when issues occur","Predictable support costs"]'::jsonb, '["Network monitoring (SNMP)","Configuration backup","Firmware management","Remote support"]'::jsonb, '["network-installation","managed-services","network-security","computer-it-support"]'::jsonb, '["corporate","education","healthcare","finance","industrial"]'::jsonb, false, 'LifeBuoy', 5)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  -- Cybersecurity
  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('network-security', 'Network Security', cat_cyber, 'Defend the perimeter and everything inside it', 'Layered network security — firewalls, segmentation, secure access and policy — engineered to your risk profile.', 'Network security is no longer a single firewall at the edge. We design layered defences.', '["A single firewall protecting a flat, exposed network.","No visibility into what''s entering or leaving the network.","Insecure remote access opening doors to attackers.","Guest and IoT devices sharing privileged network space."]'::jsonb, 'We engineer layered network security around your actual risk.', '[{"title":"Security architecture","description":"Defence-in-depth design tailored to your risk and compliance needs."},{"title":"Firewall & segmentation","description":"Next-gen firewalling and network segmentation policies."},{"title":"Secure remote access","description":"VPN and zero-trust access for staff and partners."},{"title":"Policy & controls","description":"Access policies, URL filtering and application control."},{"title":"Monitoring & alerts","description":"Logging and alerting on suspicious activity."}]'::jsonb, '["Reduced attack surface and lateral movement","Visibility into network threats","Secure remote and partner access","Stronger posture for compliance"]'::jsonb, '["Next-gen firewalls","Network segmentation","VPN / zero-trust access","URL & app filtering","SIEM logging"]'::jsonb, '["firewall-endpoint-protection","intrusion-detection","security-assessment","lan-wan","managed-services"]'::jsonb, '["finance","corporate","government","healthcare","education"]'::jsonb, true, 'ShieldCheck', 6)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('firewall-endpoint-protection', 'Firewall & Endpoint Protection', cat_cyber, 'Guard the gate and every device behind it', 'Next-gen firewalls and endpoint protection (EDR/AV) to block malware, ransomware and breaches.', 'The firewall guards the gate; endpoint protection guards every laptop, server and workstation behind it.', '["Consumer antivirus that misses modern threats.","A firewall with no threat prevention or filtering.","Ransomware reaching endpoints unchecked.","Unmanaged devices spreading infection across the network."]'::jsonb, 'We deploy next-gen firewalls with threat prevention and modern endpoint protection across your devices.', '[{"title":"Next-gen firewalling","description":"Firewall with IDS/IPS, anti-malware, web filtering and application control."},{"title":"Endpoint protection","description":"EDR/antivirus deployed across workstations and servers."},{"title":"Central management","description":"Single console for policy, alerts and remediation."},{"title":"Ransomware defence","description":"Behavioural detection and rollback where supported."},{"title":"Ongoing management","description":"Policy tuning, alerts and reporting under support plans."}]'::jsonb, '["Blocked malware, ransomware and phishing threats","Visibility and control across all endpoints","Faster detection and response","Reduced downtime and data-loss risk"]'::jsonb, '["Fortinet / SonicWall","Bitdefender EDR","Central management consoles","Threat intelligence"]'::jsonb, '["network-security","intrusion-detection","security-assessment","server-data-centre","managed-services"]'::jsonb, '["finance","corporate","healthcare","government","smb"]'::jsonb, false, 'Lock', 7)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('intrusion-detection', 'Intrusion Detection & Prevention', cat_cyber, 'Spot the threats that get past the front door', 'IDS/IPS and monitoring that detects and blocks intrusion attempts on your network.', 'Even strong firewalls can be bypassed. Intrusion detection and prevention systems watch network traffic for attack patterns.', '["Breaches that go unnoticed for weeks or months.","Firewalls that block known bad traffic but miss novel attacks.","No alerting when attackers probe the network.","Compliance requirements for continuous monitoring."]'::jsonb, 'We deploy IDS/IPS with tuned signatures and behaviour monitoring, integrated with your firewall and logging.', '[{"title":"IDS/IPS deployment","description":"Network-based intrusion detection and prevention, tuned to your environment."},{"title":"Signature & behaviour rules","description":"Curated rulesets with false-positive tuning."},{"title":"Alerting & escalation","description":"Alerts routed to the right people with clear severity."},{"title":"Logging integration","description":"Centralised logging for investigation and compliance."},{"title":"Regular tuning","description":"Ongoing rule updates under support plans."}]'::jsonb, '["Earlier detection of attacks and probing","Automated blocking of known threats","Investigation-ready logs","Stronger compliance posture"]'::jsonb, '["IDS/IPS engines","Next-gen firewall threat prevention","SIEM / log aggregation","Threat intelligence feeds"]'::jsonb, '["network-security","firewall-endpoint-protection","security-assessment","managed-services"]'::jsonb, '["finance","government","healthcare","corporate"]'::jsonb, false, 'ScanEye', 8)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('security-assessment', 'Security Assessment & Consultation', cat_cyber, 'Know your risks before attackers do', 'Practical security assessments, audits and roadmap planning — translated into clear, prioritised action.', 'You can''t defend what you don''t understand. Our security assessments evaluate your network, systems, surveillance and physical security.', '["Uncertainty about where the real risks are.","Budget spent on tools without a clear strategy.","Compliance demands you''re not sure you meet.","No independent view of your security posture."]'::jsonb, 'We assess your environment, document risks against likelihood and impact, and produce a prioritised, practical remediation roadmap.', '[{"title":"Risk assessment","description":"Identification and rating of threats across network, systems and physical security."},{"title":"Vulnerability review","description":"Scanning and review of exposed services and weak configurations."},{"title":"Gap analysis","description":"Where you stand versus best practice and any regulatory needs."},{"title":"Remediation roadmap","description":"Prioritised, cost-aware plan of what to fix first."},{"title":"Executive briefing","description":"Clear, plain-language summary for decision-makers."}]'::jsonb, '["Clarity on real risks and priorities","Defensible, documented security posture","Confident, budget-aware decision-making","Foundation for a proper security programme"]'::jsonb, '["Vulnerability scanners","Configuration review","Risk frameworks","Reporting"]'::jsonb, '["network-security","firewall-endpoint-protection","intrusion-detection","managed-services"]'::jsonb, '["finance","corporate","government","healthcare","smb"]'::jsonb, false, 'ShieldAlert', 9)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  -- Surveillance
  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('cctv-installation', 'CCTV Installation', cat_surv, 'Coverage engineered so nothing is missed', 'Professional CCTV design and installation with the right cameras in the right places.', 'Most CCTV problems aren''t the cameras — they''re the design. We design surveillance around what you need to see.', '["Cameras that capture nothing useful when an incident happens.","Blind spots at entrances, loading bays and key assets.","Footage too grainy to be useful.","Systems with no remote viewing or unreliable playback."]'::jsonb, 'We design CCTV around your risk areas, deploy quality cameras with proper lensing and night capability, and configure reliable storage and remote access.', '[{"title":"Coverage design","description":"Camera placement plan mapped to your risk areas and sightlines."},{"title":"Camera deployment","description":"Right cameras for each scene — resolution, lens, IR and WDR tuned."},{"title":"Storage & retention","description":"NVR/storage sized for your retention needs with reliable recording."},{"title":"Remote viewing","description":"Secure mobile and web access to live and recorded footage."},{"title":"Commissioning & handover","description":"Angle tuning, focus checks and user training."}]'::jsonb, '["Useable footage of the areas that matter","Deterrent and evidence when incidents occur","Reliable remote monitoring","Foundation for integration with access and alarms"]'::jsonb, '["Hikvision / Dahua cameras","4K & varifocal cameras","IR & low-light","NVR storage","Mobile/web viewing"]'::jsonb, '["ip-camera-systems","video-monitoring","nvr-dvr-solutions","structured-cabling","access-control-systems","perimeter-intrusion"]'::jsonb, '["retail","warehouse","corporate","residential","industrial","construction"]'::jsonb, true, 'Camera', 10)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('ip-camera-systems', 'IP Camera Systems', cat_surv, 'Modern IP video with the clarity and intelligence you need', 'Network-based IP camera systems with high resolution, smart analytics and scalable storage.', 'IP cameras are the modern standard — higher resolution, smarter analytics, and easier scalability.', '["Older analogue systems with poor image quality.","Need for smart features like motion alerts and analytics.","Scaling beyond what the existing system can handle.","Desire for remote, multi-site viewing on one platform."]'::jsonb, 'We deploy IP camera systems with high-resolution cameras, smart analytics and scalable NVR/storage.', '[{"title":"IP camera selection","description":"Resolution, lensing and analytics matched to each scene."},{"title":"Smart analytics","description":"Motion, line-crossing, intrusion and people/vehicle detection."},{"title":"Scalable storage","description":"NVR with RAID and retention sized to camera count."},{"title":"Multi-site viewing","description":"Centralised platform for one or many locations."},{"title":"Network integration","description":"Proper VLAN isolation for clean video traffic."}]'::jsonb, '["Sharper, more usable footage","Smarter alerts instead of constant recording review","Easier scaling as needs grow","Unified viewing across sites"]'::jsonb, '["IP cameras (4K/2K)","Edge analytics","PoE switching","NVR with RAID","VMS platforms"]'::jsonb, '["cctv-installation","video-monitoring","nvr-dvr-solutions","network-security","lan-wan"]'::jsonb, '["retail","warehouse","corporate","industrial","education"]'::jsonb, false, 'Video', 11)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('video-monitoring', 'Video Monitoring & Remote Viewing', cat_surv, 'Eyes on your premises, even when you''re away', 'Remote monitoring, live viewing and event-based alerting across single or multiple sites.', 'Installing cameras is only half the value — the other half is watching and responding.', '["Cameras installed but nobody watching them.","No alerts when something actually happens.","Can''t view footage when off-site.","Multiple sites with no unified view."]'::jsonb, 'We configure remote monitoring with live viewing, event-based alerts and a unified multi-site platform.', '[{"title":"Remote viewing setup","description":"Secure mobile and web access to live and recorded footage."},{"title":"Event alerts","description":"Push/email alerts for motion, line-crossing and intrusion events."},{"title":"Multi-site platform","description":"Unified dashboard across all your locations."},{"title":"Monitoring integration","description":"Optional integration with access control and alarms."},{"title":"User management","description":"Role-based access for staff and security teams."}]'::jsonb, '["Real-time awareness across sites","Faster response to incidents","Reduced need for constant manual monitoring","Centralised oversight of security"]'::jsonb, '["VMS / mobile apps","Push & email alerting","Cloud / on-prem platforms","Role-based access"]'::jsonb, '["cctv-installation","ip-camera-systems","nvr-dvr-solutions","access-control-systems","burglar-alarm-systems"]'::jsonb, '["retail","warehouse","hospitality","corporate","construction"]'::jsonb, false, 'MonitorPlay', 12)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('nvr-dvr-solutions', 'NVR / DVR & Storage Solutions', cat_surv, 'Reliable recording that keeps your footage when it counts', 'Network and digital video recorders with RAID storage, retention planning and redundancy.', 'Footage is only valuable if it''s still there when you need it. We deploy NVR and DVR solutions with properly sized storage.', '["Footage lost or overwritten before an incident is noticed.","Single-drive recorders with no redundancy.","Storage too small for the camera count and retention needed.","Unreliable recording that misses the moment."]'::jsonb, 'We size and deploy NVR/DVR storage with redundancy and retention planning matched to your cameras and needs.', '[{"title":"Storage sizing","description":"Capacity calculated from camera count, resolution, retention and activity."},{"title":"RAID & redundancy","description":"Disk redundancy so a failed drive doesn''t lose footage."},{"title":"Retention planning","description":"Recording schedules and retention aligned to requirements."},{"title":"Backup options","description":"Off-site or cloud backup for critical footage."},{"title":"Health monitoring","description":"Disk health monitoring and alerts under support plans."}]'::jsonb, '["Footage available when you need it — days later, not hours","Protection against drive failure","Right-sized storage, no overpaying or under-provisioning","Confident retention for compliance"]'::jsonb, '["NVR / DVR","RAID storage","Surveillance-grade disks","Cloud backup","Retention scheduling"]'::jsonb, '["cctv-installation","ip-camera-systems","video-monitoring","network-installation"]'::jsonb, '["retail","warehouse","finance","corporate","hospitality"]'::jsonb, false, 'HardDrive', 13)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  -- Access Control
  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('access-control-systems', 'Access Control Systems', cat_access, 'Decide who goes where, and when', 'Card, fob and app-based access control with audit trails, schedules and integration.', 'Keys get copied, lost and untracked. Access control systems let you decide exactly who can enter which door, when.', '["Lost or copied keys compromising security.","No record of who entered and when.","Difficulty revoking access for former staff or tenants.","Different access needs for different roles and times."]'::jsonb, 'We deploy card/fob/app access control with role-based permissions, schedules and full audit trails.', '[{"title":"Access design","description":"Door-by-door permissions, roles and schedules."},{"title":"Reader & controller deployment","description":"Readers, controllers and locking hardware installed."},{"title":"Credential management","description":"Card/fob/app enrolment and easy revocation."},{"title":"Audit trails","description":"Full entry/exit logging and reporting."},{"title":"Integration","description":"Link with CCTV, alarms and time attendance where needed."}]'::jsonb, '["Control and visibility over who enters your premises","Instant revocation — no rekeying","Audit trail for investigations and compliance","Flexible, role-based access"]'::jsonb, '["Card/fob/mobile readers","Access controllers","Management software","Electric locks & strikes"]'::jsonb, '["biometric-systems","door-access-systems","intercom-systems","cctv-installation","burglar-alarm-systems"]'::jsonb, '["corporate","finance","government","healthcare","education","warehouse"]'::jsonb, true, 'KeyRound', 14)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('biometric-systems', 'Biometric Systems', cat_access, 'Identity you can''t lose or share', 'Fingerprint and facial recognition for access control and time attendance.', 'Cards and fobs can be shared or lost — biometrics can''t. We deploy fingerprint and facial-recognition systems.', '["Shared or borrowed cards undermining access control.","Buddy-punching inflating attendance records.","Need for higher-assurance identity at sensitive doors.","Manual attendance processes prone to error."]'::jsonb, 'We deploy biometric readers for access control and time attendance.', '[{"title":"Biometric reader deployment","description":"Fingerprint and/or facial recognition at chosen doors."},{"title":"Enrolment & management","description":"User enrolment and ongoing management."},{"title":"Time & attendance","description":"Attendance records exportable for payroll."},{"title":"Access integration","description":"Biometric integrated with your access control platform."},{"title":"Reporting","description":"Attendance and access reports on demand."}]'::jsonb, '["Higher-assurance identity verification","Eliminates card sharing and buddy-punching","Accurate attendance for payroll","Strong audit trail"]'::jsonb, '["Fingerprint readers","Facial recognition","Time & attendance software","ZKTeco platforms"]'::jsonb, '["access-control-systems","door-access-systems","intercom-systems","smart-building-solutions"]'::jsonb, '["corporate","finance","government","education","industrial"]'::jsonb, false, 'Fingerprint', 15)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('door-access-systems', 'Door Access Systems', cat_access, 'Secure, reliable door hardware that just works', 'Electric locks, strikes, magnetic locks and turnstiles — installed and integrated for reliable operation.', 'An access system is only as reliable as the door hardware behind it. We supply and install electric strikes, magnetic locks, automatic doors and turnstiles.', '["Cheap locking hardware that fails or jams.","Doors that don''t reliably lock after entry.","Hardware not integrated with access control.","Bottlenecks at busy entrances."]'::jsonb, 'We install quality electric locking hardware — strikes, maglocks, automatic doors and turnstiles — integrated with your access platform.', '[{"title":"Hardware selection","description":"Right locking hardware for each door type and traffic."},{"title":"Installation","description":"Professional mounting, wiring and safety compliance."},{"title":"Access integration","description":"Hardware wired to controllers and fire-alarm safety release."},{"title":"Safety compliance","description":"Fail-safe operation and emergency egress compliance."},{"title":"Testing & handover","description":"Reliability testing under normal and emergency conditions."}]'::jsonb, '["Reliable, secure door operation","Safe, compliant emergency egress","Smooth flow at busy entrances","Hardware built to last"]'::jsonb, '["Electric strikes","Magnetic locks","Automatic doors","Turnstiles","Exit buttons & sensors"]'::jsonb, '["access-control-systems","biometric-systems","intercom-systems","fire-alarm-systems"]'::jsonb, '["corporate","government","healthcare","education","industrial"]'::jsonb, false, 'DoorOpen', 16)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('intercom-systems', 'Intercom Systems', cat_access, 'See, speak and grant access from anywhere', 'Audio/video intercoms for gates, receptions and multi-tenant buildings with remote unlock.', 'Intercoms are the bridge between security and convenience.', '["No way to verify visitors before granting access.","Staff leaving desks to open gates and doors.","Multi-tenant buildings with messy access management.","Need to answer the gate from anywhere."]'::jsonb, 'We deploy video and audio intercoms with remote unlock, multi-tenant support and access-control integration.', '[{"title":"Intercom deployment","description":"Audio/video intercoms at gates, doors and receptions."},{"title":"Remote unlock","description":"Grant access from a desk handset, mobile app or video phone."},{"title":"Multi-tenant support","description":"Directory and per-unit calling for apartments and offices."},{"title":"Access integration","description":"Intercom integrated with access control and CCTV."},{"title":"Mobile answering","description":"Answer and unlock from anywhere via app."}]'::jsonb, '["Verify visitors before granting access","Convenience without compromising security","Smooth multi-tenant access","Answer the gate from anywhere"]'::jsonb, '["IP video intercoms","Mobile intercom apps","Multi-tenant directories","Remote unlock"]'::jsonb, '["access-control-systems","door-access-systems","cctv-installation","smart-building-solutions"]'::jsonb, '["residential","corporate","hospitality","education","government"]'::jsonb, false, 'PhoneCall', 17)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  -- Alarm & Fire Safety
  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('burglar-alarm-systems', 'Burglar Alarm Systems', cat_alarm, 'Detect intruders early, before loss occurs', 'Intrusion alarm systems with sensors, sirens and remote alerts for homes and businesses.', 'A burglar alarm detects intrusion early and creates a loud, immediate response.', '["Theft discovered only after the fact.","No alert when an intruder forces entry at night.","Alarms that go off with no one to respond.","Sensors that false-trigger constantly until ignored."]'::jsonb, 'We design alarm systems with the right sensors for your risk, tuned to minimise false alarms and configured to alert the right people fast.', '[{"title":"Sensor design","description":"Contacts, motion, glass-break and vibration sensors at risk points."},{"title":"Control panel","description":"Programmable panel with arm/disarm and zone management."},{"title":"Alerting","description":"Sirens plus phone/app alerts to you or a monitoring contact."},{"title":"Tuning","description":"Zone configuration to minimise false alarms."},{"title":"Integration","description":"Link with CCTV, access control and monitoring."}]'::jsonb, '["Early detection of forced entry","Immediate deterrent and response","Remote alerts wherever you are","Lower false-alarm fatigue"]'::jsonb, '["Motion & contact sensors","Glass-break sensors","Control panels","Sirens & strobes","GSM/IP alerting"]'::jsonb, '["cctv-installation","perimeter-intrusion","access-control-systems","fire-alarm-systems","video-monitoring"]'::jsonb, '["residential","retail","warehouse","corporate","industrial"]'::jsonb, false, 'Siren', 18)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('fire-alarm-systems', 'Fire Alarm Systems', cat_alarm, 'Life-safety detection engineered to standards', 'Conventional and addressable fire alarm systems with detectors, call points and sounders.', 'Fire alarms are life-safety systems — they must detect early and alert everyone reliably.', '["No early warning of fire, endangering lives.","Systems that don''t meet safety standards or insurance requirements.","Undersized sounders that can''t be heard across the site.","No integration with access control for evacuation."]'::jsonb, 'We design and install fire alarm systems with proper detector coverage, audible/visual alerting and integration for safe evacuation.', '[{"title":"System design","description":"Detector coverage and zoning engineered to standards."},{"title":"Detector deployment","description":"Smoke, heat and flame detectors at the right locations."},{"title":"Call points & sounders","description":"Manual call points, sounders and strobes for full-site alerting."},{"title":"Panel & programming","description":"Control panel with zones, delays and evacuation logic."},{"title":"Integration","description":"Door release for evacuation and link to monitoring."}]'::jsonb, '["Early, reliable fire detection","Compliant, insurable life-safety system","Clear evacuation alerting","Integrated, safer response"]'::jsonb, '["Conventional & addressable panels","Smoke/heat/flame detectors","Sounders & strobes","Manual call points"]'::jsonb, '["fire-detection-safety","door-access-systems","burglar-alarm-systems","managed-services"]'::jsonb, '["hospitality","healthcare","education","corporate","industrial","warehouse"]'::jsonb, true, 'Bell', 19)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('fire-detection-safety', 'Fire Detection & Safety Systems', cat_alarm, 'Beyond alarms — full fire-safety engineering', 'Comprehensive fire detection, suppression support and safety systems for compliance and protection.', 'Fire safety is more than an alarm panel. We cover the wider fire-safety picture.', '["Partial fire safety with gaps in detection or egress.","Emergency lighting that fails when power is lost.","No coordinated evacuation plan or signage.","Compliance gaps that surface during inspection."]'::jsonb, 'We engineer comprehensive fire detection and safety.', '[{"title":"Detection engineering","description":"Detector selection and coverage for your premises type."},{"title":"Suppression interfaces","description":"Integration with suppression and shutdown systems."},{"title":"Emergency lighting","description":"Lighting that guides evacuation during power loss."},{"title":"Signage & egress","description":"Evacuation signage and exit routing support."},{"title":"Compliance documentation","description":"System records for inspection and insurance."}]'::jsonb, '["Comprehensive, compliant fire safety","Safer evacuation under any condition","Reduced liability and insurability","Coordinated, documented protection"]'::jsonb, '["Detection systems","Suppression interfaces","Emergency lighting","Evacuation signage"]'::jsonb, '["fire-alarm-systems","door-access-systems","managed-services","server-data-centre"]'::jsonb, '["hospitality","healthcare","education","industrial","warehouse","corporate"]'::jsonb, false, 'Flame', 20)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('perimeter-intrusion', 'Perimeter Intrusion Detection', cat_alarm, 'Catch intruders at the fence, not the door', 'Perimeter sensors, beam detectors and fence systems for early intrusion warning.', 'The earlier you detect an intruder, the more time you have to respond.', '["Intruders detected only after they''re inside.","Large perimeters that can''t be watched constantly.","Need to trigger CCTV recording before entry.","Outdoor environments that defeat indoor sensors."]'::jsonb, 'We deploy outdoor perimeter detection integrated with CCTV and alarms for early warning.', '[{"title":"Perimeter assessment","description":"Boundary survey to choose the right detection technology."},{"title":"Sensor deployment","description":"Active/passive beams, fence or vibration sensors."},{"title":"CCTV integration","description":"Triggered recording and PTZ camera response."},{"title":"Alarm & alerts","description":"Sirens and remote alerts on detection."},{"title":"Environmental tuning","description":"Tuning to reduce false triggers from animals and weather."}]'::jsonb, '["Earlier detection at the boundary","Time to respond before entry","Triggered CCTV for evidence","Layered defence with alarms and surveillance"]'::jsonb, '["Active infrared beams","Fence & vibration sensors","Outdoor detectors","CCTV integration"]'::jsonb, '["cctv-installation","burglar-alarm-systems","video-monitoring","access-control-systems"]'::jsonb, '["industrial","warehouse","construction","residential","government"]'::jsonb, false, 'ShieldAlert', 21)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  -- IT Infrastructure
  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('server-data-centre', 'Server & Data-Centre Solutions', cat_infra, 'Resilient compute, storage and racks', 'Server deployment, rack fit-out, storage and backup for reliable business compute.', 'Your business runs on servers and storage. We design and deploy server and small-data-centre solutions.', '["Servers sitting under a desk with no redundancy or backup.","No proper rack, cooling or power protection.","Data at risk from failed drives with no backup.","Recovery that would take days, not hours."]'::jsonb, 'We engineer server and data-centre solutions — compute, storage, racks, UPS and backup — built for resilience and fast recovery.', '[{"title":"Architecture & sizing","description":"Compute, storage and network sized to your workload."},{"title":"Rack & environment","description":"Racks, cooling, cable management and layout."},{"title":"Power & UPS","description":"UPS protection and power distribution."},{"title":"Virtualisation & storage","description":"Hypervisors, RAID storage and capacity planning."},{"title":"Backup & recovery","description":"Backup strategy with tested recovery."}]'::jsonb, '["Reliable business compute","Protected power and cooling","Data protected by backup and redundancy","Faster recovery from failure"]'::jsonb, '["Virtualisation (Hyper-V/Proxmox)","RAID/NAS storage","Racks & UPS","Veeam backup","APC power"]'::jsonb, '["computer-it-support","managed-services","network-security","firewall-endpoint-protection","network-installation"]'::jsonb, '["corporate","finance","healthcare","education","industrial"]'::jsonb, true, 'ServerCog', 22)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('computer-it-support', 'Computer & IT Support', cat_infra, 'Responsive IT support that keeps people productive', 'Helpdesk, on-site and remote IT support for workstations, users and day-to-day operations.', 'When computers, printers or accounts stop working, productivity stops. We provide responsive IT support.', '["IT issues that stall work for hours or days.","No responsive support when something breaks.","Recurring problems nobody gets to the root of.","Staff wasting time on IT issues instead of their jobs."]'::jsonb, 'We provide responsive remote and on-site IT support — fast helpdesk and root-cause resolution.', '[{"title":"Helpdesk support","description":"Remote support for user and system issues."},{"title":"On-site support","description":"Engineers on-site for hands-on issues."},{"title":"Workstation management","description":"Setup, updates and troubleshooting of computers."},{"title":"User & account support","description":"Account, email and access management."},{"title":"Root-cause resolution","description":"Fixing underlying issues, not just symptoms."}]'::jsonb, '["Faster resolution of IT issues","Less downtime, more productivity","Predictable IT support costs","One number to call for IT"]'::jsonb, '["Remote support tooling","Helpdesk ticketing","Workstation management","User provisioning"]'::jsonb, '["managed-services","server-data-centre","network-maintenance","systems-installation-maintenance"]'::jsonb, '["corporate","smb","education","healthcare","retail"]'::jsonb, false, 'MonitorCog', 23)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('systems-installation-maintenance', 'Systems Installation & Maintenance', cat_infra, 'Deployed right, maintained properly', 'Professional installation and ongoing maintenance for IT and security systems.', 'Systems work best when they''re installed properly and maintained regularly.', '["Systems installed without proper configuration or testing.","No maintenance, so systems degrade and fail.","Multiple vendors with no overall ownership.","Equipment past warranty with no support path."]'::jsonb, 'We install and maintain your IT and security systems — proper deployment plus scheduled, preventive maintenance.', '[{"title":"Professional installation","description":"Systems deployed, configured and tested to standard."},{"title":"Preventive maintenance","description":"Scheduled servicing to keep systems healthy."},{"title":"Health monitoring","description":"Monitoring that catches issues early."},{"title":"Lifecycle management","description":"Warranty, refresh and replacement planning."},{"title":"Single ownership","description":"One partner accountable across systems."}]'::jsonb, '["Systems that work reliably for longer","Fewer surprise failures","Predictable maintenance costs","One accountable partner"]'::jsonb, '["Installation & commissioning","Preventive maintenance","Monitoring","Lifecycle planning"]'::jsonb, '["managed-services","computer-it-support","network-maintenance","server-data-centre"]'::jsonb, '["corporate","smb","education","healthcare","industrial"]'::jsonb, false, 'Cog', 24)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('smart-building-solutions', 'Smart Building Solutions', cat_infra, 'Connected, intelligent buildings', 'Integrated building systems — security, automation, lighting and energy — working as one.', 'Modern buildings don''t need a dozen disconnected systems. We design smart-building solutions.', '["A dozen systems that don''t talk to each other.","Energy waste from unmanaged lighting and climate.","No automation for routine building functions.","Complexity that frustrates facility teams."]'::jsonb, 'We design integrated smart-building solutions — security, automation and energy under one platform.', '[{"title":"Integration design","description":"Architecture unifying security, automation and energy."},{"title":"Automation","description":"Schedules and rules for lighting, climate and access."},{"title":"Energy management","description":"Monitoring and control to reduce waste."},{"title":"Single platform","description":"One interface for building operations."},{"title":"Scalability","description":"Architecture that grows with the building."}]'::jsonb, '["Simpler, smarter building operations","Lower energy costs","Better security and comfort","One interface instead of many"]'::jsonb, '["Building automation","IoT integration","Lighting & climate control","Unified platforms"]'::jsonb, '["access-control-systems","intercom-systems","cctv-installation","wifi-installation","server-data-centre"]'::jsonb, '["corporate","hospitality","residential","government","healthcare"]'::jsonb, false, 'Building2', 25)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;

  INSERT INTO "Service" ("slug", "name", "categoryId", "tagline", "shortDescription", "overview", "problem", "solution", "deliverables", "benefits", "tech", "relatedServices", "relatedIndustries", "featured", "iconName", "sortOrder") VALUES
  ('managed-services', 'Managed Services & Technical Support', cat_infra, 'Your IT and security, fully managed', 'Ongoing managed services — monitoring, maintenance, support and improvement — under one agreement.', 'The best systems are the ones that keep working because someone is looking after them.', '["Unpredictable IT and security costs.","Systems that degrade because nobody maintains them.","Slow, reactive support.","No visibility into system health or risk."]'::jsonb, 'We manage your IT and security under one agreement — proactive monitoring, maintenance, support and improvement.', '[{"title":"Continuous monitoring","description":"24/7 monitoring of critical systems and security."},{"title":"Preventive maintenance","description":"Scheduled servicing across IT and security."},{"title":"Priority support","description":"Defined SLAs and direct access to engineers."},{"title":"Reporting & visibility","description":"Regular health and activity reporting."},{"title":"Continuous improvement","description":"Recommendations to strengthen and optimise over time."}]'::jsonb, '["Predictable costs and fewer surprises","Healthier systems that fail less","Faster, prioritised response","Strategic partner, not just a vendor"]'::jsonb, '["Monitoring platforms","RMM tooling","Ticketing & SLAs","Security management"]'::jsonb, '["computer-it-support","network-maintenance","network-security","systems-installation-maintenance"]'::jsonb, '["corporate","smb","finance","healthcare","education"]'::jsonb, true, 'LifeBuoy', 26)
  ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "categoryId" = EXCLUDED."categoryId", "updatedAt" = CURRENT_TIMESTAMP;
END $$;

